<?php $__env->startSection('content'); ?><h2><?php echo e($title); ?></h2><?php if($errors->any()): ?><div class="error"><ul><?php $__currentLoopData = $errors->all(); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $error): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><?php echo e($error); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ul></div><?php endif; ?><form class="editor" method="POST" action="<?php echo e($method==='POST' ? (isset($parent) ? route($route.'.store', $parent) : route($route.'.store')) : (isset($parent) ? route($route.'.update', [$parent, $item]) : route($route.'.update', $item))); ?>"><?php echo csrf_field(); ?> <?php if($method!=='POST'): ?><?php echo method_field($method); ?><?php endif; ?> <?php $__currentLoopData = $fields; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $field): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($field); ?><?php if(in_array($field,['is_enabled','opens_new_tab','is_active'])): ?><input type="checkbox" name="<?php echo e($field); ?>" value="1" <?php if(old($field, $item->$field ?? true)): echo 'checked'; endif; ?>><?php elseif(str_contains($field,'body')||str_contains($field,'subtitle')||$field==='value'||$field==='settings'): ?><textarea name="<?php echo e($field); ?>"><?php echo e(old($field, is_array($item->$field) ? json_encode($item->$field) : $item->$field)); ?></textarea><?php else: ?><input name="<?php echo e($field); ?>" value="<?php echo e(old($field, $item->$field)); ?>" <?php if(str_contains($field,'url')): ?> type="url" <?php else: ?> type="text" <?php endif; ?>><?php endif; ?></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <button>Save</button><a class="button" href="<?php echo e(isset($parent) ? route($route.'.index', $parent) : route($route.'.index')); ?>">Cancel</a></form><?php $__env->stopSection(); ?>

